const upsertBankRule = `-- name: UpsertBankRule :one
INSERT INTO bank_rules (taxpayer_id, match_type, match_value, debit_credit, kind, kind_detail, created_by)
VALUES ($1, $2, $3, $4, $5, $6, $7)
ON CONFLICT (taxpayer_id, match_type, match_value, debit_credit)
DO UPDATE SET kind = EXCLUDED.kind, kind_detail = EXCLUDED.kind_detail, created_by = EXCLUDED.created_by
RETURNING id, uuid, taxpayer_id, match_type, match_value, debit_credit, kind, kind_detail, hits, created_by, created_at, updated_at
`

type UpsertBankRuleParams struct {
	TaxpayerID  int64       `json:"taxpayer_id"`
	MatchType   string      `json:"match_type"`
	MatchValue  string      `json:"match_value"`
	DebitCredit pgtype.Text `json:"debit_credit"`
	Kind        string      `json:"kind"`
	KindDetail  string      `json:"kind_detail"`
	CreatedBy   pgtype.Int8 `json:"created_by"`
}

func (q *Queries) UpsertBankRule(ctx context.Context, arg UpsertBankRuleParams) (BankRule, error) {
	row := q.db.QueryRow(ctx, upsertBankRule,
		arg.TaxpayerID,
		arg.MatchType,
		arg.MatchValue,
		arg.DebitCredit,
		arg.Kind,
		arg.KindDetail,
		arg.CreatedBy,
	)
	var i BankRule
	err := row.Scan(
		&i.ID,
		&i.Uuid,
		&i.TaxpayerID,
		&i.MatchType,
		&i.MatchValue,
		&i.DebitCredit,
		&i.Kind,
		&i.KindDetail,
		&i.Hits,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
